func (this *TextLayout) DrawInPixelsGcXInPointsYInPointsSelectionStartSelectionEndSelectionForegroundSelectionBackgroundFlags(gcLike GCLike, xInPoints int32, yInPoints int32, selectionStart int32, selectionEnd int32, selectionForegroundLike ColorLike, selectionBackgroundLike ColorLike, flags int32) {
	var gc *GC
	if gcLike != nil {
		gc = gcLike.AsGC()
	}
	_ = gc
	var selectionForeground *Color
	if selectionForegroundLike != nil {
		selectionForeground = selectionForegroundLike.AsColor()
	}
	_ = selectionForeground
	var selectionBackground *Color
	if selectionBackgroundLike != nil {
		selectionBackground = selectionBackgroundLike.AsColor()
	}
	_ = selectionBackground
	this.ComputeRuns(gc)
	if gc == (nil) {
		Error(ERROR_NULL_ARGUMENT)
	}
	if gc.impl.isDisposed_() {
		Error(ERROR_INVALID_ARGUMENT)
	}
	if selectionForeground != (nil) && selectionForeground.impl.isDisposed_() {
		Error(ERROR_INVALID_ARGUMENT)
	}
	if selectionBackground != (nil) && selectionBackground.impl.isDisposed_() {
		Error(ERROR_INVALID_ARGUMENT)
	}
	var length int32 = jrt.StringLength(this.text)
	if length == 0 && flags == 0 {
		return
	}
	yInPoints += this.verticalIndentInPoints
	var hdc int64 = gc.Handle
	var clip *Rectangle = gc.GetClippingInPixels()
	var data *GCData = gc.data
	var gdipGraphics int64 = data.GdipGraphics
	var foreground int32 = data.Foreground
	var linkColor int32 = win32.OSGetSysColor(win32.OSCOLOR_HOTLIGHT)
	var alpha int32 = data.Alpha
	var gdip bool = gdipGraphics != 0
	var gdipForeground int64 = int64(0)
	var gdipLinkColor int64 = int64(0)
	var state int32 = 0
	if gdip {
		gc.CheckGC(GCFOREGROUND)
		gdipForeground = gc.GetFgBrush()
	} else {
		state = win32.OSSaveDC(hdc)
		if (data.Style & MIRRORED) != 0 {
			win32.OSSetLayout(hdc, win32.OSGetLayout(hdc)|win32.OSLAYOUT_RTL)
		}
	}
	var hasSelection bool = selectionStart <= selectionEnd && selectionStart != -1 && selectionEnd != -1
	var gdipSelBackground int64 = int64(0)
	var gdipSelForeground int64 = int64(0)
	var gdipFont int64 = int64(0)
	var lastHFont int64 = int64(0)
	var selBackground int64 = int64(0)
	var selForeground int32 = 0
	if hasSelection || ((flags&LAST_LINE_SELECTION) != 0 && (flags&(FULL_SELECTION|DELIMITER_SELECTION)) != 0) {
		var fgSel int32
		if selectionForeground != (nil) {
			fgSel = selectionForeground.Handle
		} else {
			fgSel = win32.OSGetSysColor(win32.OSCOLOR_HIGHLIGHTTEXT)
		}
		var bgSel int32
		if selectionBackground != (nil) {
			bgSel = selectionBackground.Handle
		} else {
			bgSel = win32.OSGetSysColor(win32.OSCOLOR_HIGHLIGHT)
		}
		if gdip {
			gdipSelBackground = this.CreateGdipBrush(bgSel, alpha)
			gdipSelForeground = this.CreateGdipBrush(fgSel, alpha)
		} else {
			selBackground = win32.OSCreateSolidBrush(bgSel)
			selForeground = fgSel
		}
		if hasSelection {
			selectionStart = this.TranslateOffset(int32(math.Min(float64(int32(math.Max(float64(0), float64(selectionStart)))), float64(length-1))))
			selectionEnd = this.TranslateOffset(int32(math.Min(float64(int32(math.Max(float64(0), float64(selectionEnd)))), float64(length-1))))
		}
	}
	var x int32 = Win32DPIUtilsPointToPixelOverload3(this.impl.getDevice_(), xInPoints, this.GetZoom(gc))
	var rect *win32.RECT = win32.NewRECT()
	win32.OSSetBkMode(hdc, win32.OSTRANSPARENT)
	for line := int32(0); line < int32(len(this.runs)); line++ {
		var drawX int32 = x + this.GetLineIndentInPixel(line)
		var drawY int32 = Win32DPIUtilsPointToPixelOverload3(this.impl.getDevice_(), yInPoints+this.lineY[line], this.GetZoom(gc))
		var lineRuns []*TextLayout_StyleItem = this.runs[line]
		var drawYWithLineHeight int32 = Win32DPIUtilsPointToPixelOverload3(this.impl.getDevice_(), yInPoints+this.lineY[line+1]-this.lineSpacingInPoints, this.GetZoom(gc))
		var drawYWithLineHeightWithSpacing int32 = Win32DPIUtilsPointToPixelOverload3(this.impl.getDevice_(), yInPoints+this.lineY[line+1], this.GetZoom(gc))
		var lineHeight int32 = Win32DPIUtilsPointToPixelOverload3(this.impl.getDevice_(), this.lineY[line+1]-this.lineY[line]-this.lineSpacingInPoints, this.GetZoom(gc))
		var lineHeightWithSpacing int32 = drawYWithLineHeightWithSpacing - drawY
		var extents bool = false
		if (flags&(FULL_SELECTION|DELIMITER_SELECTION)) != 0 && (hasSelection || (flags&LAST_LINE_SELECTION) != 0) {
			if line == int32(len(this.runs))-1 && (flags&LAST_LINE_SELECTION) != 0 {
				extents = true
			} else {
				var run *TextLayout_StyleItem = lineRuns[int32(len(lineRuns))-1]
				if run.lineBreak && !run.softBreak {
					if selectionStart <= run.start && run.start <= selectionEnd {
						extents = true
					}
				} else {
					var endOffset int32 = run.start + run.length - 1
					if selectionStart <= endOffset && endOffset < selectionEnd && (flags&FULL_SELECTION) != 0 {
						extents = true
					}
				}
			}
			if extents {
				var width int32
				if (flags & FULL_SELECTION) != 0 {
					width = 0x6FFFFFF
				} else {
					width = lineHeightWithSpacing / 3
				}
				if gdip {
					win32.GdipGraphics_FillRectangle(gdipGraphics, gdipSelBackground, drawX+this.lineWidthInPixels[line], drawY, width, lineHeightWithSpacing)
				} else {
					win32.OSSelectObject(hdc, selBackground)
					win32.OSPatBlt(hdc, drawX+this.lineWidthInPixels[line], drawY, width, lineHeightWithSpacing, win32.OSPATCOPY)
				}
			}
		}
		if drawX > clip.X+clip.Width {
			continue
		}
		if drawX+this.lineWidthInPixels[line] < clip.X {
			continue
		}
		var alignmentX int32 = drawX
		for _, run := range lineRuns {
			if run.length == 0 {
				continue
			}
			if drawX > clip.X+clip.Width {
				break
			}
			if drawX+run.width >= clip.X {
				if !run.lineBreak || run.softBreak {
					if extents {
						win32.OSSetRect(rect, drawX, drawY, drawX+run.width, drawYWithLineHeightWithSpacing)
					} else {
						win32.OSSetRect(rect, drawX, drawY, drawX+run.width, drawYWithLineHeight)
					}
					if gdip {
						this.DrawRunBackgroundGDIP(run, gdipGraphics, rect, selectionStart, selectionEnd, alpha, gdipSelBackground, hasSelection)
					} else {
						this.DrawRunBackground(run, hdc, rect, selectionStart, selectionEnd, selBackground, hasSelection)
					}
				}
			}
			drawX += run.width
		}
		var baselineInPixels int32 = int32(math.Max(float64(0), float64(Win32DPIUtilsPointToPixelOverload3(this.impl.getDevice_(), this.ascent, this.GetZoom(gc)))))
		var lineUnderlinePos int32 = 0
		for _, run := range lineRuns {
			baselineInPixels = int32(math.Max(float64(baselineInPixels), float64(Win32DPIUtilsPointToPixelOverload3(this.impl.getDevice_(), run.ascentInPoints, this.GetZoom(gc)))))
			lineUnderlinePos = int32(math.Min(float64(lineUnderlinePos), float64(run.underlinePos)))
		}
		var borderClip *win32.RECT = nil
		var underlineClip *win32.RECT = nil
		var strikeoutClip *win32.RECT = nil
		var pRect *win32.RECT = nil
		drawX = alignmentX
		for i := int32(0); i < int32(len(lineRuns)); i++ {
			var run *TextLayout_StyleItem = lineRuns[i]
			var style *TextStyle = run.style
			var hasAdorners bool = style != (nil) && (style.Underline || style.Strikeout || style.BorderStyle != NONE)
			if run.length == 0 {
				continue
			}
			if drawX > clip.X+clip.Width {
				break
			}
			if drawX+run.width >= clip.X {
				var skipTab bool = run.tab && !hasAdorners
				if !skipTab && (!run.lineBreak || run.softBreak) && !(style != (nil) && style.Metrics != (nil)) {
					win32.OSSetRect(rect, drawX, drawY, drawX+run.width, drawY+lineHeight)
					if gdip {
						var hFont int64 = this.GetItemFont(run, gc)
						if hFont != lastHFont {
							lastHFont = hFont
							if gdipFont != 0 {
								win32.GdipFont_delete(gdipFont)
							}
							var oldFont int64 = win32.OSSelectObject(hdc, hFont)
							gdipFont = win32.GdipFont_new(hdc, hFont)
							win32.OSSelectObject(hdc, oldFont)
							if gdipFont == 0 {
								Error(ERROR_NO_HANDLES)
							}
							if !win32.GdipFont_IsAvailable(gdipFont) {
								win32.GdipFont_delete(gdipFont)
								gdipFont = int64(0)
							}
						}
						var gdipFg int64 = gdipForeground
						if style != (nil) && style.Underline && style.UnderlineStyle == UNDERLINE_LINK {
							if gdipLinkColor == 0 {
								gdipLinkColor = this.CreateGdipBrush(linkColor, alpha)
							}
							gdipFg = gdipLinkColor
						}
						if gdipFont != 0 && !run.analysis.FNoGlyphIndex {
							pRect = this.DrawRunTextGDIP(gc, gdipGraphics, run, rect, gdipFont, baselineInPixels, gdipFg, gdipSelForeground, selectionStart, selectionEnd, alpha)
						} else {
							var fg int32
							if style != (nil) && style.Underline && style.UnderlineStyle == UNDERLINE_LINK {
								fg = linkColor
							} else {
								fg = foreground
							}
							pRect = this.DrawRunTextGDIPRaster(gc, gdipGraphics, run, rect, baselineInPixels, fg, selForeground, selectionStart, selectionEnd)
						}
						underlineClip = this.DrawUnderlineGDIP(gc, gdipGraphics, x, drawY+baselineInPixels, lineUnderlinePos, drawY+lineHeight, lineRuns, i, gdipFg, gdipSelForeground, underlineClip, pRect, selectionStart, selectionEnd, alpha, clip)
						strikeoutClip = this.DrawStrikeoutGDIP(gc, gdipGraphics, x, drawY+baselineInPixels, lineRuns, i, gdipFg, gdipSelForeground, strikeoutClip, pRect, selectionStart, selectionEnd, alpha, clip)
						borderClip = this.DrawBorderGDIP(gdipGraphics, x, drawY, lineHeight, lineRuns, i, gdipFg, gdipSelForeground, borderClip, pRect, selectionStart, selectionEnd, alpha, clip)
					} else {
						var fg int32
						if style != (nil) && style.Underline && style.UnderlineStyle == UNDERLINE_LINK {
							fg = linkColor
						} else {
							fg = foreground
						}
						pRect = this.DrawRunText(gc, hdc, run, rect, baselineInPixels, fg, selForeground, selectionStart, selectionEnd)
						underlineClip = this.DrawUnderline(gc, hdc, x, drawY+baselineInPixels, lineUnderlinePos, drawY+lineHeight, lineRuns, i, fg, selForeground, underlineClip, pRect, selectionStart, selectionEnd, clip)
						strikeoutClip = this.DrawStrikeout(gc, hdc, x, drawY+baselineInPixels, lineRuns, i, fg, selForeground, strikeoutClip, pRect, selectionStart, selectionEnd, clip)
						borderClip = this.DrawBorder(hdc, x, drawY, lineHeight, lineRuns, i, fg, selForeground, borderClip, pRect, selectionStart, selectionEnd, clip)
					}
				}
			}
			drawX += run.width
		}
	}
	if gdipSelBackground != 0 {
		win32.GdipSolidBrush_delete(gdipSelBackground)
	}
	if gdipSelForeground != 0 {
		win32.GdipSolidBrush_delete(gdipSelForeground)
	}
	if gdipLinkColor != 0 {
		win32.GdipSolidBrush_delete(gdipLinkColor)
	}
	if gdipFont != 0 {
		win32.GdipFont_delete(gdipFont)
	}
	if state != 0 {
		win32.OSRestoreDC(hdc, state)
	}
	if selBackground != 0 {
		win32.OSDeleteObject(selBackground)
	}
}

func (this *TextLayout) DrawBorder(hdc int64, x int32, y int32, lineHeight int32, line []*TextLayout_StyleItem, index int32, color int32, selectionColor int32, clipRect *win32.RECT, pRect *win32.RECT, selectionStart int32, selectionEnd int32, drawClipLike RectangleLike) *win32.RECT {
	var drawClip *Rectangle
	if drawClipLike != nil {
		drawClip = drawClipLike.AsRectangle()
	}
	_ = drawClip
	var run *TextLayout_StyleItem = line[index]
	var style *TextStyle = run.style
	if style == (nil) {
		return nil
	}
	if style.BorderStyle == NONE {
		return nil
	}
	clipRect = this.AddClipRect(run, clipRect, pRect, selectionStart, selectionEnd)
	var lastRunVisible bool = drawClip != (nil) && (x+run.x+run.width) > (drawClip.X+drawClip.Width)
	if index+1 >= int32(len(line)) || lastRunVisible || line[index+1].lineBreak || !style.IsAdherentBorder(line[index+1].style) {
		var left int32 = run.x
		var start int32 = run.start
		var end int32 = run.start + run.length - 1
		for i := int32(index); i > 0 && style.IsAdherentBorder(line[i-1].style); i-- {
			left = line[i-1].x
			start = int32(math.Min(float64(start), float64(line[i-1].start)))
			end = int32(math.Max(float64(end), float64(line[i-1].start+line[i-1].length-1)))
		}
		var hasSelection bool = selectionStart <= selectionEnd && selectionStart != -1 && selectionEnd != -1
		var fullSelection bool = hasSelection && selectionStart <= start && end <= selectionEnd
		if style.BorderColor != (nil) {
			color = style.BorderColor.Handle
			clipRect = nil
		} else {
			if fullSelection {
				color = selectionColor
				clipRect = nil
			} else {
				if style.Foreground != (nil) {
					color = style.Foreground.Handle
				}
			}
		}
		var lineWidth int32 = 1
		var pattern int32 = 1
		var lineStyle int32 = win32.OSPS_SOLID
		switch style.BorderStyle {
		case BORDER_SOLID:
			break
		case BORDER_DASH:
			{
				lineStyle = win32.OSPS_DASH
				pattern = 4
				break
			}
		case BORDER_DOT:
			{
				lineStyle = win32.OSPS_DOT
				pattern = 2
				break
			}
		}
		var oldBrush int64 = win32.OSSelectObject(hdc, win32.OSGetStockObject(win32.OSNULL_BRUSH))
		var logBrush *win32.LOGBRUSH = win32.NewLOGBRUSH()
		logBrush.LbStyle = win32.OSBS_SOLID
		logBrush.LbColor = color
		var newPen int64 = win32.OSExtCreatePen(lineStyle|win32.OSPS_GEOMETRIC, lineWidth, logBrush, 0, nil)
		var oldPen int64 = win32.OSSelectObject(hdc, newPen)
		var drawRect *win32.RECT = win32.NewRECT()
		win32.OSSetRect(drawRect, x+left, y, x+run.x+run.width, y+lineHeight)
		if drawClip != (nil) {
			if drawRect.Left < drawClip.X {
				var remainder int32 = drawRect.Left % pattern
				drawRect.Left = drawClip.X/pattern*pattern + remainder - pattern
			}
			if drawRect.Right > drawClip.X+drawClip.Width {
				var remainder int32 = drawRect.Right % pattern
				drawRect.Right = (drawClip.X+drawClip.Width)/pattern*pattern + remainder + pattern
			}
		}
		win32.OSRectangle(hdc, drawRect.Left, drawRect.Top, drawRect.Right, drawRect.Bottom)
		win32.OSSelectObject(hdc, oldPen)
		win32.OSDeleteObject(newPen)
		if clipRect != (nil) {
			var state int32 = win32.OSSaveDC(hdc)
			if clipRect.Left == -1 {
				clipRect.Left = 0
			}
			if clipRect.Right == -1 {
				clipRect.Right = 0x7ffff
			}
			win32.OSIntersectClipRect(hdc, clipRect.Left, clipRect.Top, clipRect.Right, clipRect.Bottom)
			logBrush.LbColor = selectionColor
			var selPen int64 = win32.OSExtCreatePen(lineStyle|win32.OSPS_GEOMETRIC, lineWidth, logBrush, 0, nil)
			oldPen = win32.OSSelectObject(hdc, selPen)
			win32.OSRectangle(hdc, drawRect.Left, drawRect.Top, drawRect.Right, drawRect.Bottom)
			win32.OSRestoreDC(hdc, state)
			win32.OSSelectObject(hdc, oldPen)
			win32.OSDeleteObject(selPen)
		}
		win32.OSSelectObject(hdc, oldBrush)
		return nil
	}
	return clipRect
}

func (this *TextLayout) DrawBorderGDIP(graphics int64, x int32, y int32, lineHeight int32, line []*TextLayout_StyleItem, index int32, color int64, selectionColor int64, clipRect *win32.RECT, pRect *win32.RECT, selectionStart int32, selectionEnd int32, alpha int32, drawClipLike RectangleLike) *win32.RECT {
	var drawClip *Rectangle
	if drawClipLike != nil {
		drawClip = drawClipLike.AsRectangle()
	}
	_ = drawClip
	var run *TextLayout_StyleItem = line[index]
	var style *TextStyle = run.style
	if style == (nil) {
		return nil
	}
	if style.BorderStyle == NONE {
		return nil
	}
	clipRect = this.AddClipRect(run, clipRect, pRect, selectionStart, selectionEnd)
	var lastRunVisible bool = drawClip != (nil) && (x+run.x+run.width) > (drawClip.X+drawClip.Width)
	if index+1 >= int32(len(line)) || lastRunVisible || line[index+1].lineBreak || !style.IsAdherentBorder(line[index+1].style) {
		var left int32 = run.x
		var start int32 = run.start
		var end int32 = run.start + run.length - 1
		for i := int32(index); i > 0 && style.IsAdherentBorder(line[i-1].style); i-- {
			left = line[i-1].x
			start = int32(math.Min(float64(start), float64(line[i-1].start)))
			end = int32(math.Max(float64(end), float64(line[i-1].start+line[i-1].length-1)))
		}
		var hasSelection bool = selectionStart <= selectionEnd && selectionStart != -1 && selectionEnd != -1
		var fullSelection bool = hasSelection && selectionStart <= start && end <= selectionEnd
		var brush int64 = color
		if style.BorderColor != (nil) {
			brush = this.CreateGdipBrushColorAlpha(style.BorderColor, alpha)
			clipRect = nil
		} else {
			if fullSelection {
				brush = selectionColor
				clipRect = nil
			} else {
				if style.Foreground != (nil) {
					brush = this.CreateGdipBrushColorAlpha(style.Foreground, alpha)
				}
			}
		}
		var lineWidth int32 = 1
		var lineStyle int32 = win32.GdipDashStyleSolid
		switch style.BorderStyle {
		case BORDER_SOLID:
			break
		case BORDER_DASH:
			lineStyle = win32.GdipDashStyleDash
			break
		case BORDER_DOT:
			lineStyle = win32.GdipDashStyleDot
			break
		}
		var pen int64 = win32.GdipPen_new(brush, float32(lineWidth))
		win32.GdipPen_SetDashStyle(pen, lineStyle)
		win32.GdipGraphics_SetPixelOffsetMode(graphics, win32.GdipPixelOffsetModeNone)
		var smoothingMode int32 = win32.GdipGraphics_GetSmoothingMode(graphics)
		win32.GdipGraphics_SetSmoothingMode(graphics, win32.GdipSmoothingModeNone)
		if clipRect != (nil) {
			var gstate int32 = win32.GdipGraphics_Save(graphics)
			if clipRect.Left == -1 {
				clipRect.Left = 0
			}
			if clipRect.Right == -1 {
				clipRect.Right = 0x7ffff
			}
			var gdipRect *win32.Rect = win32.NewRect()
			gdipRect.X = clipRect.Left
			gdipRect.Y = clipRect.Top
			gdipRect.Width = clipRect.Right - clipRect.Left
			gdipRect.Height = clipRect.Bottom - clipRect.Top
			win32.GdipGraphics_SetClipGraphicsRectCombineMode(graphics, gdipRect, win32.GdipCombineModeExclude)
			win32.GdipGraphics_DrawRectangle(graphics, pen, x+left, y, run.x+run.width-left-1, lineHeight-1)
			win32.GdipGraphics_Restore(graphics, gstate)
			gstate = win32.GdipGraphics_Save(graphics)
			win32.GdipGraphics_SetClipGraphicsRectCombineMode(graphics, gdipRect, win32.GdipCombineModeIntersect)
			var selPen int64 = win32.GdipPen_new(selectionColor, float32(lineWidth))
			win32.GdipPen_SetDashStyle(selPen, lineStyle)
			win32.GdipGraphics_DrawRectangle(graphics, selPen, x+left, y, run.x+run.width-left-1, lineHeight-1)
			win32.GdipPen_delete(selPen)
			win32.GdipGraphics_Restore(graphics, gstate)
		} else {
			win32.GdipGraphics_DrawRectangle(graphics, pen, x+left, y, run.x+run.width-left-1, lineHeight-1)
		}
		win32.GdipGraphics_SetPixelOffsetMode(graphics, win32.GdipPixelOffsetModeHalf)
		win32.GdipGraphics_SetSmoothingMode(graphics, smoothingMode)
		win32.GdipPen_delete(pen)
		if brush != selectionColor && brush != color {
			win32.GdipSolidBrush_delete(brush)
		}
		return nil
	}
	return clipRect
}

func (this *TextLayout) DrawRunBackground(runLike TextLayout_StyleItemLike, hdc int64, rect *win32.RECT, selectionStart int32, selectionEnd int32, selBrush int64, hasSelection bool) {
	var run *TextLayout_StyleItem
	if runLike != nil {
		run = runLike.AsTextLayout_StyleItem()
	}
	_ = run
	var end int32 = run.start + run.length - 1
	var fullSelection bool = hasSelection && selectionStart <= run.start && selectionEnd >= end
	if fullSelection {
		win32.OSSelectObject(hdc, selBrush)
		win32.OSPatBlt(hdc, rect.Left, rect.Top, rect.Right-rect.Left, rect.Bottom-rect.Top, win32.OSPATCOPY)
	} else {
		if run.style != (nil) && run.style.Background != (nil) {
			var bg int32 = run.style.Background.Handle
			var hBrush int64 = win32.OSCreateSolidBrush(bg)
			var oldBrush int64 = win32.OSSelectObject(hdc, hBrush)
			win32.OSPatBlt(hdc, rect.Left, rect.Top, rect.Right-rect.Left, rect.Bottom-rect.Top, win32.OSPATCOPY)
			win32.OSSelectObject(hdc, oldBrush)
			win32.OSDeleteObject(hBrush)
		}
		var partialSelection bool = hasSelection && !(selectionStart > end || run.start > selectionEnd)
		if partialSelection {
			this.GetPartialSelection(run, selectionStart, selectionEnd, rect)
			win32.OSSelectObject(hdc, selBrush)
			win32.OSPatBlt(hdc, rect.Left, rect.Top, rect.Right-rect.Left, rect.Bottom-rect.Top, win32.OSPATCOPY)
		}
	}
}

