	var runs *jrt.List = jrt.NewList(itemCount + this.stylesCount + (end+TextLayoutMAX_RUN_LENGTH-1)/TextLayoutMAX_RUN_LENGTH)
	var scriptItem *win32.SCRIPT_ITEM = win32.NewSCRIPT_ITEM()
	var itemLimit int32 = -1
	var nextItemIndex int32 = 0
	var linkBefore bool = false
	var merge bool = itemCount > TextLayoutTOO_MANY_RUNS
