	item.start = end
	win32.OSMoveMemoryOverload81(scriptItem, items+int64(itemCount*win32.SCRIPT_ITEMSizeof), win32.SCRIPT_ITEMSizeof)
	item.analysis = scriptItem.A
	runs.Add(item)
