func (this *TextLayout) Shape(hdc int64, runLike TextLayout_StyleItemLike, chars []uint16, glyphCount []int32, maxGlyphs int32, sp *win32.SCRIPT_PROPERTIES) bool {
	var run *TextLayout_StyleItem
	if runLike != nil {
		run = runLike.AsTextLayout_StyleItem()
	}
	_ = run
	var useCMAPcheck bool = !sp.FComplex && !run.analysis.FNoGlyphIndex
	if useCMAPcheck {
		var glyphs []int16 = make([]int16, int32(len(chars)))
		if win32.OSScriptGetCMap(hdc, run.psc, chars, int32(len(chars)), 0, glyphs) != win32.OSS_OK {
			if run.psc != 0 {
				win32.OSScriptFreeCache(run.psc)
				glyphCount[0] = 0
				win32.OSMoveMemoryOverload79(run.psc, make([]int64, 1), win32.CPTR_SIZEOF)
			}
			return false
		}
	}
	var scriptShaprHr int32 = win32.OSScriptShape(hdc, run.psc, chars, int32(len(chars)), maxGlyphs, run.analysis, run.glyphs, run.clusters, run.visAttrs, glyphCount)
	if scriptShaprHr == win32.OSS_OK {
		run.glyphCount = glyphCount[0]
		if useCMAPcheck {
			return true
		}
		if run.analysis.FNoGlyphIndex {
			return true
		}
		var fp *win32.SCRIPT_FONTPROPERTIES = win32.NewSCRIPT_FONTPROPERTIES()
		fp.CBytes = win32.SCRIPT_FONTPROPERTIESSizeof
		win32.OSScriptGetFontProperties(hdc, run.psc, fp)
		var glyphs []int16 = make([]int16, glyphCount[0])
		win32.OSMoveMemoryOverload10(glyphs, run.glyphs, int32(len(glyphs))*2)
		var i int32
		for i = 0; i < int32(len(glyphs)); i++ {
			if int32(glyphs[i]) == int32(fp.WgDefault) {
				break
			}
		}
		if i == int32(len(glyphs)) {
			return true
		}
	}
	if run.psc != 0 {
		win32.OSScriptFreeCache(run.psc)
		glyphCount[0] = 0
		win32.OSMoveMemoryOverload79(run.psc, make([]int64, 1), win32.CPTR_SIZEOF)
	}
	run.glyphCount = 0
	return false
}

func (this *TextLayout) CreateMetafileWithChars(hdc int64, hFont int64, chars []uint16, charCount int32) int64 {
	var hHeap int64 = win32.OSGetProcessHeap()
	var nativeStringSize int32 = charCount * 2
	var nativeString int64 = win32.OSHeapAlloc(hHeap, win32.OSHEAP_ZERO_MEMORY, nativeStringSize)
	win32.OSMoveMemoryOverload12(nativeString, chars, nativeStringSize)
	var ssa int64 = win32.OSHeapAlloc(hHeap, win32.OSHEAP_ZERO_MEMORY, win32.OSSCRIPT_STRING_ANALYSIS_sizeof())
	var metaFileDc int64 = win32.OSCreateEnhMetaFile(hdc, nil, nil, nil)
	var oldMetaFont int64 = win32.OSSelectObject(metaFileDc, hFont)
	var flags int32 = win32.OSSSA_METAFILE | win32.OSSSA_FALLBACK | win32.OSSSA_GLYPHS | win32.OSSSA_LINK
	if win32.OSScriptStringAnalyse(metaFileDc, nativeString, charCount, 0, -1, flags, 0, nil, nil, int64(0), int64(0), int64(0), ssa) == win32.OSS_OK {
		win32.OSScriptStringOut(ssa, 0, 0, 0, nil, 0, 0, false)
		win32.OSScriptStringFree(ssa)
	}
	win32.OSHeapFree(hHeap, 0, nativeString)
	win32.OSHeapFree(hHeap, 0, ssa)
	win32.OSSelectObject(metaFileDc, oldMetaFont)
	return win32.OSCloseEnhMetaFile(metaFileDc)
}

