func (this *TextLayout) ValidadeOffset(offset int32, step int32) int32 {
	offset = this.UntranslateOffset(offset)
	return this.TranslateOffset(offset + step)
}

func (this *TextLayout) String() string {
	if this.impl.isDisposed_() {
		return "TextLayout {*DISPOSED*}"
	}
	return "TextLayout {}"
}

func (this *TextLayout) TranslateOffset(offset int32) int32 {
	var length int32 = jrt.StringLength(this.text)
	if length == 0 {
		return offset
	}
	if this.segments == (nil) {
		return offset
	}
	var nSegments int32 = int32(len(this.segments))
	if nSegments == 0 {
		return offset
	}
	if this.segmentsChars == (nil) {
		if nSegments == 1 {
			return offset
		}
		if nSegments == 2 {
			if this.segments[0] == 0 && this.segments[1] == length {
				return offset
			}
		}
	}
	for i := int32(0); i < nSegments && offset-i >= this.segments[i]; i++ {
		offset++
	}
	return offset
}

func (this *TextLayout) UntranslateOffset(offset int32) int32 {
	var length int32 = jrt.StringLength(this.text)
	if length == 0 {
		return offset
	}
	if this.segments == (nil) {
		return offset
	}
	var nSegments int32 = int32(len(this.segments))
	if nSegments == 0 {
		return offset
	}
	if this.segmentsChars == (nil) {
		if nSegments == 1 {
			return offset
		}
		if nSegments == 2 {
			if this.segments[0] == 0 && this.segments[1] == length {
				return offset
			}
		}
	}
	for i := int32(0); i < nSegments && offset > this.segments[i]; i++ {
		offset--
	}
	return offset
}

