func (this *TextLayout_MetricsAdapter) SetFixedLineMetrics(metricsLike FontMetricsLike) {
	var metrics *FontMetrics
	if metricsLike != nil {
		metrics = metricsLike.AsFontMetrics()
	}
	_ = metrics
	if metrics == (nil) {
		this.wantMetricsInPixels = nil
		return
	}
	var result *win32.TEXTMETRIC = win32.NewTEXTMETRIC()
	result.TmAscent = metrics.Handle.TmAscent
	result.TmDescent = metrics.Handle.TmDescent
	result.TmHeight = metrics.Handle.TmHeight
	result.TmInternalLeading = metrics.Handle.TmInternalLeading
	result.TmAveCharWidth = 0
	this.wantMetricsInPixels = result
}

func (this *TextLayout_MetricsAdapter) CalcYAdjust(realMetricsInPixels *win32.TEXTMETRIC) int32 {
	return (this.wantMetricsInPixels.TmAscent - realMetricsInPixels.TmAscent)
}

func (this *TextLayout_MetricsAdapter) CalcYAdjustHdc(hdc int64) int32 {
	win32.OSGetTextMetrics(hdc, this.realMetricsInPixels)
	return this.CalcYAdjust(this.realMetricsInPixels)
}

